/**
 * Mock SSH server used by the Remote Bash end-to-end tests.
 *
 * It is a *real* SSH server (ssh2.Server) listening on 127.0.0.1:0, with a
 * deliberately small, deterministic remote environment:
 *
 *   - host keys: ed25519 keys generated by `ssh2.utils.generateKeyPairSync`
 *     (can be hot-replaced through `setHostKey()` to test fingerprint TOFU);
 *   - auth: password (`tester` / `secret`) and publickey (keys passed through
 *     `authorizedKeys`, including keys whose private half is passphrase
 *     protected);
 *   - exec: `/bin/bash -c <command>` in a fresh per-connection working dir with
 *     a stable HOME (so `~` keeps pointing at the same directory across
 *     connections) and a PATH that starts with the mock's `bin/` dir. The
 *     `bin/sudo` shim implements `sudo -S -p '' -- bash -lc '<cmd>'`: it reads
 *     the first stdin line as the password and only then runs the command;
 *   - shell: `/bin/bash -s` (persistent cd/export across writes);
 *   - sftp: implemented on top of node:fs and contained to `dataDir`.
 *
 * The data dir layout is:
 *
 *   <dataDir>/home            -> stable $HOME (also the initial SFTP cwd)
 *   <dataDir>/work/conn-*     -> per-connection exec/shell working directory
 *   <dataDir>/bin/sudo        -> the sudo shim described above
 *
 * Usage:
 *
 *   const mock = createMockServer({ dataDir, authorizedKeys: [pub] })
 *   const { port } = await mock.listen()
 *   ... mock.fingerprint, mock.homeDir, mock.setHostKey(pair) ...
 *   await mock.close()
 */

import ssh2 from 'ssh2'
import { createHash } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import os from 'node:os'
import { spawn } from 'node:child_process'

const { Server, utils } = ssh2
const { OPEN_MODE, STATUS_CODE } = utils.sftp

const LOCAL_HOST = '127.0.0.1'
const DEFAULT_USERNAME = 'tester'
const DEFAULT_PASSWORD = 'secret'
const DEFAULT_SUDO_PASSWORD = 'sudo-secret'

export const MOCK_USERNAME = DEFAULT_USERNAME
export const MOCK_PASSWORD = DEFAULT_PASSWORD
export const MOCK_SUDO_PASSWORD = DEFAULT_SUDO_PASSWORD

/** OpenSSH-style SHA256 fingerprint of a raw SSH public-key blob. */
export function fingerprintOf(publicKeyBlob) {
  const digest = createHash('sha256').update(publicKeyBlob).digest('base64')
  return `SHA256:${digest.replace(/=+$/, '')}`
}

function toBuffer(value) {
  if (Buffer.isBuffer(value)) return value
  return Buffer.from(String(value))
}

/** Normalise anything key-ish into `{ privateKey, publicKey, blob, keyType, fingerprint }`. */
function normalizeHostKey(input) {
  let privateKey
  let passphrase
  let publicKey

  if (input == null) {
    const pair = utils.generateKeyPairSync('ed25519')
    privateKey = pair.private
    publicKey = pair.public
  } else if (Buffer.isBuffer(input) || typeof input === 'string') {
    privateKey = input
  } else if (typeof input === 'object' && input !== null) {
    if (input.private != null) {
      privateKey = input.private
      publicKey = input.public
      passphrase = input.passphrase
    } else if (input.key != null) {
      privateKey = input.key
      passphrase = input.passphrase
    } else {
      throw new TypeError('hostKey must be a key pair, a private key string/buffer, or undefined')
    }
  } else {
    throw new TypeError('hostKey must be a key pair, a private key string/buffer, or undefined')
  }

  const parsed = utils.parseKey(privateKey, passphrase)
  if (parsed instanceof Error) throw new Error(`Cannot parse host key: ${parsed.message}`)
  const key = Array.isArray(parsed) ? parsed[0] : parsed
  const blob = key.getPublicSSH()
  if (!blob) throw new Error('Cannot derive public host key')
  return {
    privateKey,
    publicKey: publicKey ?? blob,
    blob,
    keyType: key.type,
    fingerprint: fingerprintOf(blob),
  }
}

function parseAuthorizedKeyList(list) {
  const keys = []
  for (const entry of list) {
    const parsed = utils.parseKey(toBuffer(entry))
    if (parsed instanceof Error) throw new Error(`Cannot parse authorized key: ${parsed.message}`)
    const key = Array.isArray(parsed) ? parsed[0] : parsed
    keys.push(key.getPublicSSH())
  }
  return keys
}

function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`
}

/** Protocol-faithful sudo shim: prompt before reading; cached/NOPASSWD never reads stdin. */
function renderSudoShim(sudoPassword) {
  return `#!/bin/bash
__rb_prompt=''
while [ "$#" -gt 0 ]; do
  case "$1" in
    -p) shift; __rb_prompt="$1"; shift ;;
    -S|-k|-n|-E|-H|-A|-b|-i|-s) shift ;;
    --) shift; break ;;
    -*) shift ;;
    *) break ;;
  esac
done
if [ "\${RB_TEST_SUDO_MODE:-password}" = password ]; then
  printf '%s' "$__rb_prompt" >&2
  IFS= read -r __rb_sudo_password || __rb_sudo_password=''
  if [ "$__rb_sudo_password" != ${shellQuote(sudoPassword)} ]; then
    echo 'sudo: a password is required' >&2
    exit 1
  fi
fi
exec "$@"
`
}

function attrsFromStat(st) {
  return {
    mode: st.mode,
    uid: st.uid,
    gid: st.gid,
    size: st.size,
    atime: st.atimeMs,
    mtime: st.mtimeMs,
  }
}

function formatLongname(name, st) {
  const type = st.isDirectory() ? 'd' : st.isSymbolicLink() ? 'l' : '-'
  const mode = st.mode & 0o7777
  const perms = [
    mode & 0o400 ? 'r' : '-',
    mode & 0o200 ? 'w' : '-',
    mode & 0o100 ? 'x' : '-',
    mode & 0o040 ? 'r' : '-',
    mode & 0o020 ? 'w' : '-',
    mode & 0o010 ? 'x' : '-',
    mode & 0o004 ? 'r' : '-',
    mode & 0o002 ? 'w' : '-',
    mode & 0o001 ? 'x' : '-',
  ].join('')
  const mtime = new Date(st.mtimeMs).toUTCString()
  return `${type}${perms} 1 tester tester ${st.size} ${mtime} ${name}`
}

function openFlagsToString(flags) {
  const read = (flags & OPEN_MODE.READ) !== 0
  const write = (flags & OPEN_MODE.WRITE) !== 0
  const creat = (flags & OPEN_MODE.CREAT) !== 0
  const trunc = (flags & OPEN_MODE.TRUNC) !== 0
  const append = (flags & OPEN_MODE.APPEND) !== 0
  if (append) return 'a'
  if (read && write) return trunc ? 'w+' : creat ? 'a+' : 'r+'
  if (write) return trunc ? 'w' : 'a'
  return 'r'
}

/**
 * Create a mock SSH server. Nothing is listening until `listen()` is awaited.
 *
 * @param {object} [options]
 * @param {string} [options.dataDir] directory backing SFTP/HOME; a temp dir is
 *   created (and removed on close) when omitted.
 * @param {object|string|Buffer} [options.hostKey] ed25519 key pair (or private
 *   key); generated when omitted.
 * @param {Array<string|Buffer>} [options.authorizedKeys] public keys accepted
 *   for publickey auth.
 * @param {string} [options.username]
 * @param {string} [options.password]
 * @param {string} [options.sudoPassword]
 */
export function createMockServer(options = {}) {
  const {
    dataDir: dataDirOption,
    hostKey: hostKeyOption,
    authorizedKeys = [],
    username = DEFAULT_USERNAME,
    password = DEFAULT_PASSWORD,
    sudoPassword = DEFAULT_SUDO_PASSWORD,
  } = options

  const ownsDataDir = !dataDirOption
  const dataDir = dataDirOption
    ? path.resolve(dataDirOption)
    : fs.mkdtempSync(path.join(os.tmpdir(), 'rb-mock-ssh-'))
  fs.mkdirSync(dataDir, { recursive: true })

  const homeDir = path.join(dataDir, 'home')
  const workRoot = path.join(dataDir, 'work')
  const binDir = path.join(dataDir, 'bin')
  fs.mkdirSync(homeDir, { recursive: true })
  fs.mkdirSync(workRoot, { recursive: true })
  fs.mkdirSync(binDir, { recursive: true })
  const sudoPath = path.join(binDir, 'sudo')
  fs.writeFileSync(sudoPath, renderSudoShim(sudoPassword))
  fs.chmodSync(sudoPath, 0o755)

  const childEnv = {
    HOME: homeDir,
    USER: username,
    LOGNAME: username,
    PATH: `${binDir}:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin`,
    SHELL: '/bin/bash',
    TERM: 'dumb',
    LANG: 'C',
    LC_ALL: 'C',
  }

  let keyInfo = normalizeHostKey(hostKeyOption)
  const authorized = parseAuthorizedKeyList(authorizedKeys)

  let server = null
  let listing = false
  let listenPort = null
  const clients = new Set()
  const children = new Set()
  // macOS resolves /var -> /private/var: always compare canonical paths so a
  // client that spells an absolute path with the un-resolved prefix still
  // passes the containment check.
  const dataDirReal = fs.realpathSync.native(dataDir)
  let connectionCount = 0
  let ptyRequests = 0

  const mock = {
    get connectionCount() { return connectionCount },
    get ptyRequests() { return ptyRequests },
    /** Data directory backing HOME + SFTP (also available as `sftpRoot`). */
    dataDir,
    get sftpRoot() {
      return dataDir
    },
    homeDir,
    workRoot,
    username,
    password,
    sudoPassword,
    get port() {
      return listenPort
    },
    get listening() {
      return listing
    },
    get fingerprint() {
      return keyInfo.fingerprint
    },
    get keyType() {
      return keyInfo.keyType
    },
    get publicKey() {
      return keyInfo.publicKey
    },
    /** Host key blob (Buffer) used to derive the fingerprint. */
    get publicKeyBlob() {
      return keyInfo.blob
    },
    /** Create a fresh ed25519 key pair (useful for "host key changed" tests). */
    generateHostKey() {
      return utils.generateKeyPairSync('ed25519')
    },
    /**
     * Replace the server host key. When listening, the listener is closed and
     * reopened on the same port with the new key (the port has to stay stable
     * so tests can assert TOFU against one known host entry).
     */
    async setHostKey(nextKey) {
      const next = normalizeHostKey(nextKey)
      keyInfo = next
      if (!server) return mock
      const port = listenPort
      listing = false
      await stopListening()
      await startListening(port)
      return mock
    },
    /** Add a public key (string/Buffer) accepted for publickey auth. */
    addAuthorizedKey(key) {
      const parsed = utils.parseKey(toBuffer(key))
      if (parsed instanceof Error) throw new Error(`Cannot parse authorized key: ${parsed.message}`)
      const k = Array.isArray(parsed) ? parsed[0] : parsed
      authorized.push(k.getPublicSSH())
      return mock
    },
    async listen() {
      if (server) return mock
      await startListening(0)
      return mock
    },
    async close() {
      listing = false
      await stopListening()
      for (const child of children) {
        try {
          child.kill('SIGKILL')
        } catch {
          /* ignore */
        }
      }
      children.clear()
      if (ownsDataDir) fs.rmSync(dataDir, { recursive: true, force: true })
      return mock
    },
  }

  function makeServer() {
    listing = true
    const instance = new Server(
      {
        hostKeys: [keyInfo.privateKey],
        keepaliveInterval: 0,
        keepaliveCountMax: 0,
      },
      onConnection,
    )
    instance.on('error', () => {
      /* listener errors are surfaced through listen() */
    })
    return instance
  }

  function startListening(port) {
    const instance = makeServer()
    return new Promise((resolve, reject) => {
      const onError = (err) => {
        instance.removeListener('listening', onListening)
        server = null
        listing = false
        reject(err)
      }
      const onListening = () => {
        instance.removeListener('error', onError)
        server = instance
        listenPort = instance.address().port
        resolve(mock)
      }
      instance.once('error', onError)
      instance.once('listening', onListening)
      instance.listen(port, LOCAL_HOST)
    })
  }

  async function stopListening() {
    const instance = server
    server = null
    listenPort = null
    if (!instance) return
    for (const client of clients) {
      try {
        client.end()
      } catch {
        /* ignore */
      }
      try {
        client._sock?.destroy?.()
      } catch {
        /* ignore */
      }
    }
    clients.clear()
    await new Promise((resolve) => {
      const timer = setTimeout(resolve, 2000)
      timer.unref?.()
      try {
        instance.close(() => {
          clearTimeout(timer)
          resolve()
        })
      } catch {
        clearTimeout(timer)
        resolve()
      }
    })
  }

  function onConnection(client) {
    clients.add(client)
    const connIndex = ++connectionCount
    const workDir = fs.mkdtempSync(path.join(workRoot, `conn-${connIndex}-`))

    client.on('close', () => clients.delete(client))
    client.on('error', () => {
      /* a client that disappears mid-flight must not crash the test process */
    })

    client.on('authentication', (ctx) => {
      if (ctx.username !== username) return ctx.reject()
      if (ctx.method === 'password') {
        return ctx.password === password ? ctx.accept() : ctx.reject(['password', 'publickey'])
      }
      if (ctx.method === 'publickey') {
        const blob = toBuffer(ctx.key.data)
        const ok = authorized.some((candidate) => candidate.equals(blob))
        return ok ? ctx.accept() : ctx.reject(['password', 'publickey'])
      }
      return ctx.reject(['password', 'publickey'])
    })

    client.on('ready', () => {
      client.on('session', (accept) => {
        const session = accept()
        // This fixture is pipe-backed: reject PTYs instead of silently pretending to be a terminal.
        session.on('pty', (_acceptPty, rejectPty) => { ptyRequests += 1; rejectPty?.() })
        session.on('env', (acceptEnv) => acceptEnv && acceptEnv())
        session.on('exec', (acceptExec, _reject, info) => {
          handleExec(acceptExec(), info.command, workDir)
        })
        session.on('shell', (acceptShell) => {
          handleShell(acceptShell(), workDir)
        })
        session.on('sftp', (acceptSftp) => {
          handleSftp(acceptSftp(), workDir)
        })
      })
    })
  }

  function handleExec(stream, command, workDir) {
    let child = null
    let finished = false

    const finish = (code) => {
      if (finished) return
      finished = true
      try {
        stream.exit(code ?? 1)
      } catch {
        /* channel may already be gone */
      }
      try {
        stream.end()
      } catch {
        /* ignore */
      }
    }

    try {
      child = spawn('/bin/bash', ['-c', command], {
        cwd: workDir,
        env: childEnv,
        stdio: ['pipe', 'pipe', 'pipe'],
      })
    } catch (error) {
      try {
        stream.stderr.write(`mock-ssh: cannot spawn shell: ${error.message}\n`)
      } catch {
        /* ignore */
      }
      return finish(1)
    }

    children.add(child)
    child.stdout.on('data', (data) => {
      try {
        stream.write(data)
      } catch {
        /* ignore */
      }
    })
    child.stderr.on('data', (data) => {
      try {
        stream.stderr.write(data)
      } catch {
        /* ignore */
      }
    })
    child.on('error', (error) => {
      try {
        stream.stderr.write(`mock-ssh: ${error.message}\n`)
      } catch {
        /* ignore */
      }
      finish(1)
    })
    child.on('close', (code, signal) => {
      children.delete(child)
      finish(code === null ? (signal ? 137 : 1) : code)
    })

    stream.on('data', (data) => {
      if (child.stdin.writable) child.stdin.write(data)
    })
    stream.on('end', () => {
      if (child.stdin.writable) child.stdin.end()
    })
    stream.on('close', () => {
      if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL')
    })
  }

  function handleShell(stream, workDir) {
    const child = spawn('/bin/bash', ['-s'], {
      cwd: workDir,
      env: childEnv,
      stdio: ['pipe', 'pipe', 'pipe'],
    })
    children.add(child)
    child.stdout.on('data', (data) => {
      try {
        stream.write(data)
      } catch {
        /* ignore */
      }
    })
    child.stderr.on('data', (data) => {
      try {
        stream.stderr.write(data)
      } catch {
        /* ignore */
      }
    })
    child.on('error', (error) => {
      try {
        stream.stderr.write(`mock-ssh: ${error.message}\n`)
      } catch {
        /* ignore */
      }
      try {
        stream.exit(1)
        stream.end()
      } catch {
        /* ignore */
      }
    })
    child.on('close', (code) => {
      children.delete(child)
      try {
        stream.exit(code ?? 0)
        stream.end()
      } catch {
        /* ignore */
      }
    })
    stream.on('data', (data) => {
      if (child.stdin.writable) child.stdin.write(data)
    })
    stream.on('end', () => {
      if (child.stdin.writable) child.stdin.end()
    })
    stream.on('close', () => {
      if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL')
    })
  }

  function handleSftp(sftp, workDir) {
    /** handle buffer (4 bytes) -> { kind: 'file'|'dir', fd?, entries? } */
    const handles = new Map()
    let nextHandle = 1
    /** current SFTP working directory, starts in HOME like a real server */
    let cwd = homeDir

    function allocHandle(record) {
      const handle = Buffer.alloc(4)
      handle.writeUInt32BE(nextHandle++, 0)
      handles.set(handle.toString('hex'), record)
      return handle
    }

    function getHandle(handle) {
      return handles.get(Buffer.from(handle).toString('hex'))
    }

    function canonicalize(target) {
      const absolute = path.resolve(target)
      try {
        return fs.realpathSync.native(absolute)
      } catch (error) {
        if (error.code !== 'ENOENT' && error.code !== 'ENOTDIR') throw error
        // Non-existent leaf: resolve the parent so /var -> /private/var (and
        // other symlinked ancestors) is normalised before comparing.
        const parentReal = fs.realpathSync.native(path.dirname(absolute))
        return path.join(parentReal, path.basename(absolute))
      }
    }

    function resolvePath(input, followLeaf = true) {
      let target
      if (input === '') target = cwd
      else if (input === '~') target = homeDir
      else if (input.startsWith('~/')) target = path.join(homeDir, input.slice(2))
      else if (path.isAbsolute(input)) target = input
      else target = path.resolve(cwd, input)
      const resolved = followLeaf ? canonicalize(target) : path.join(canonicalize(path.dirname(target)), path.basename(target))
      const rel = path.relative(dataDirReal, resolved)
      if (rel !== '' && (rel.startsWith('..') || path.isAbsolute(rel))) {
        const error = new Error(`Path escapes the mock SFTP root: ${input}`)
        error.code = 'ESANDBOX'
        throw error
      }
      return resolved
    }

    function statusForError(reqid, error) {
      if (error && (error.code === 'ENOENT' || error.code === 'ENOTDIR')) {
        return sftp.status(reqid, STATUS_CODE.NO_SUCH_FILE)
      }
      if (error && (error.code === 'EACCES' || error.code === 'ESANDBOX')) {
        return sftp.status(reqid, STATUS_CODE.PERMISSION_DENIED)
      }
      return sftp.status(reqid, STATUS_CODE.FAILURE)
    }

    function replyStat(reqid, statFn, target) {
      try {
        sftp.attrs(reqid, attrsFromStat(statFn(target)))
      } catch (error) {
        statusForError(reqid, error)
      }
    }

    sftp.on('OPEN', (reqid, filename, flags, attrs) => {
      try {
        const target = resolvePath(filename)
        const mode = attrs && typeof attrs.mode === 'number' ? attrs.mode & 0o7777 : 0o644
        const fd = fs.openSync(target, openFlagsToString(flags), mode)
        sftp.handle(reqid, allocHandle({ kind: 'file', fd, path: target }))
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('CLOSE', (reqid, handle) => {
      const record = getHandle(handle)
      if (!record) return sftp.status(reqid, STATUS_CODE.FAILURE)
      handles.delete(Buffer.from(handle).toString('hex'))
      try {
        if (record.kind === 'file' && record.fd !== undefined) fs.closeSync(record.fd)
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('READ', (reqid, handle, offset, length) => {
      const record = getHandle(handle)
      if (!record || record.kind !== 'file') return sftp.status(reqid, STATUS_CODE.FAILURE)
      try {
        const buffer = Buffer.alloc(length)
        const bytesRead = fs.readSync(record.fd, buffer, 0, length, offset)
        if (bytesRead === 0) return sftp.status(reqid, STATUS_CODE.EOF)
        sftp.data(reqid, buffer.subarray(0, bytesRead))
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('WRITE', (reqid, handle, offset, data) => {
      const record = getHandle(handle)
      if (!record || record.kind !== 'file') return sftp.status(reqid, STATUS_CODE.FAILURE)
      try {
        fs.writeSync(record.fd, data, 0, data.length, offset)
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('FSTAT', (reqid, handle) => {
      const record = getHandle(handle)
      if (!record) return sftp.status(reqid, STATUS_CODE.FAILURE)
      if (record.kind === 'dir') {
        try {
          return sftp.attrs(reqid, attrsFromStat(fs.statSync(record.path)))
        } catch (error) {
          return statusForError(reqid, error)
        }
      }
      try {
        sftp.attrs(reqid, attrsFromStat(fs.fstatSync(record.fd)))
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('STAT', (reqid, filename) => {
      let target
      try {
        target = resolvePath(filename)
      } catch (error) {
        return statusForError(reqid, error)
      }
      replyStat(reqid, fs.statSync, target)
    })

    sftp.on('LSTAT', (reqid, filename) => {
      let target
      try {
        target = resolvePath(filename, false)
      } catch (error) {
        return statusForError(reqid, error)
      }
      replyStat(reqid, fs.lstatSync, target)
    })

    sftp.on('SETSTAT', (reqid, filename, attrs) => {
      try {
        const target = resolvePath(filename)
        if (attrs && typeof attrs.mode === 'number') fs.chmodSync(target, attrs.mode & 0o7777)
        if (attrs && (typeof attrs.atime === 'number' || typeof attrs.mtime === 'number')) {
          const st = fs.statSync(target)
          const atime = typeof attrs.atime === 'number' ? attrs.atime / 1000 : st.atimeMs / 1000
          const mtime = typeof attrs.mtime === 'number' ? attrs.mtime / 1000 : st.mtimeMs / 1000
          fs.utimesSync(target, atime, mtime)
        }
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('FSETSTAT', (reqid, handle, attrs) => {
      const record = getHandle(handle)
      if (!record || record.kind !== 'file') return sftp.status(reqid, STATUS_CODE.FAILURE)
      try {
        if (attrs && typeof attrs.mode === 'number') fs.fchmodSync(record.fd, attrs.mode & 0o7777)
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('OPENDIR', (reqid, filename) => {
      try {
        const target = resolvePath(filename)
        const st = fs.statSync(target)
        if (!st.isDirectory()) return sftp.status(reqid, STATUS_CODE.FAILURE)
        const names = fs.readdirSync(target).sort()
        const entries = names.map((name) => {
          const entryPath = path.join(target, name)
          const entryStat = fs.lstatSync(entryPath)
          return {
            filename: name,
            longname: formatLongname(name, entryStat),
            attrs: attrsFromStat(entryStat),
          }
        })
        // Like OpenSSH's sftp-server, include . and .. entries.
        const dot = fs.lstatSync(target)
        entries.unshift(
          { filename: '..', longname: formatLongname('..', dot), attrs: attrsFromStat(dot) },
          { filename: '.', longname: formatLongname('.', dot), attrs: attrsFromStat(dot) },
        )
        sftp.handle(reqid, allocHandle({ kind: 'dir', path: target, entries }))
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('READDIR', (reqid, handle) => {
      const record = getHandle(handle)
      if (!record || record.kind !== 'dir') return sftp.status(reqid, STATUS_CODE.FAILURE)
      if (!record.entries || record.entries.length === 0) return sftp.status(reqid, STATUS_CODE.EOF)
      const batch = record.entries.splice(0, 64)
      sftp.name(reqid, batch)
    })

    sftp.on('MKDIR', (reqid, filename, attrs) => {
      try {
        const target = resolvePath(filename)
        const mode = attrs && typeof attrs.mode === 'number' ? attrs.mode & 0o7777 : 0o755
        fs.mkdirSync(target, { mode })
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('RMDIR', (reqid, filename) => {
      try {
        fs.rmdirSync(resolvePath(filename))
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('REMOVE', (reqid, filename) => {
      try {
        fs.unlinkSync(resolvePath(filename))
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('RENAME', (reqid, oldPath, newPath) => {
      try {
        fs.renameSync(resolvePath(oldPath), resolvePath(newPath))
        sftp.status(reqid, STATUS_CODE.OK)
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('REALPATH', (reqid, filename) => {
      try {
        const target = resolvePath(filename)
        let st
        try {
          st = fs.statSync(target)
        } catch {
          st = null
        }
        // RFC 4254 SFTP has no chdir: REALPATH only canonicalises the name.
        sftp.name(reqid, [
          {
            filename: target,
            longname: st ? formatLongname(target, st) : target,
            attrs: st ? attrsFromStat(st) : {},
          },
        ])
      } catch (error) {
        statusForError(reqid, error)
      }
    })

    sftp.on('close', () => {
      for (const [, record] of handles) {
        if (record.kind === 'file' && record.fd !== undefined) {
          try {
            fs.closeSync(record.fd)
          } catch {
            /* ignore */
          }
        }
      }
      handles.clear()
    })

    // The initial SFTP cwd is HOME (real servers start there); `workDir` keeps
    // the signature symmetric with exec/shell even though it is not used yet.
    void workDir
  }

  return mock
}

export default createMockServer
